-- Content source corrections, 19 November 2026.
-- Brings live database content into line with the decisions recorded in the
-- Content Source Pack (items R1 to R23). Safe to run more than once.

-- R1: helplines in the harassment support wizard
UPDATE harassment_wizard_contacts
   SET name = 'SSAFA Forcesline',
       description = 'Free, confidential helpline for serving personnel, veterans and families, independent of the chain of command',
       phone = '0800 260 6767',
       availability = 'Mon-Thu 9am-5pm, Fri 9am-4pm'
 WHERE name = 'SSAFA';
DELETE FROM harassment_wizard_contacts WHERE name = 'Confidential Support Line';
UPDATE harassment_wizard_guidance
   SET message = replace(replace(message, 'Use the Confidential Support Line.', 'Call SSAFA Forcesline on 0800 260 6767.'), 'use the Confidential Support Line.', 'call SSAFA Forcesline on 0800 260 6767.')
 WHERE message ILIKE '%Confidential Support Line%';
UPDATE harassment_wizard_contacts
   SET phone = NULL,
       description = 'Independent oversight of the Service Complaints process. Contact through the online form on the Ombudsman website',
       availability = 'Online contact form'
 WHERE name = 'Service Complaints Ombudsman' AND phone = '020 7877 3450';

-- R3: military perks
UPDATE perks_facts SET detail = 'While you serve, Defence Medical Services provide your healthcare and dental care free of charge.'
 WHERE detail ILIKE 'You get priority NHS treatment%';
UPDATE perks_facts SET detail = 'You get 38 days of leave a year. By law, most full-time workers are entitled to at least 28 days (including bank holidays).'
 WHERE detail ILIKE 'You get 38 days leave per year%';
-- R3 and R4: unsourced quotes, one naming a single service
UPDATE perks_regret_stories SET is_active = false;

-- R4: no single-service naming
UPDATE service_family_support_orgs SET description = 'Independent support and advocacy for Naval Service families.'
 WHERE description ILIKE '%Royal Navy and Royal Marines families%';

-- R17: exercise and depression claim
UPDATE brain_myths
   SET statement = 'Regular exercise can help with low mood and mild depression.',
       explanation = 'The NHS recommends regular exercise for low mood: it may improve your mood and help you sleep better. If low mood lasts more than 2 weeks, speak to a GP.'
 WHERE statement = 'Exercise is as effective as medication for mild depression.';

