-- R20: school confidentiality
UPDATE tips SET title = 'School Staff Who Can Help',
       content = 'Your form tutor, head of year or school counsellor can help with school, friendship and emotional worries. What you say is kept private, unless they are worried you or someone else may be at risk of harm. Then they may need to tell someone who can help keep you safe.'
 WHERE content ILIKE '%Everything is confidential%';

-- R23: LGBTQ+ deployment safety and intersex figure
UPDATE lgbtq_terms SET meaning = replace(meaning, 'More common than many realise — about 1.7% of people.', 'Estimates of how many people are intersex vary widely, depending on which conditions are included.') WHERE meaning LIKE '%1.7%%';
UPDATE lgbtq_deploy_regions SET countries = replace(countries, 'Oman, Singapore, Sri Lanka', 'Oman, Sri Lanka') WHERE countries LIKE '%Singapore%';
UPDATE lgbtq_deploy_regions SET advice = replace(advice, 'Imprisonment of 10+ years for same-sex activity. Exercise extreme caution.', 'Same-sex activity can lead to long prison sentences. Exercise extreme caution. Always check the latest FCDO travel advice for the country before you go.') WHERE advice LIKE '%Imprisonment of 10+ years%';

